// N-Queens II (#52) on bitmasks: taken columns and diagonals are three ints
int full = (1 << n) - 1, total = 0;
void Place(int cols, int d1, int d2) {
    if (cols == full) { total++; return; }
    int free = full & ~(cols | d1 | d2);       // free columns of this row
    while (free != 0) {
        int bit = free & -free;                // the lowest free column
        free -= bit;
        Place(cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);
    }
}
